var v: Node = get_tree().current_scene.find_child("OperaExplorationV1",true,false)
var backgrounds: int = 0
var fixtures: int = 0
var crests: int = 0
var residents: Array[int] = []
var owners: Dictionary = {}
var all_pot: bool = true
for child: Node in v.world.get_children():
	if child is Sprite2D:
		var sprite: Sprite2D = child as Sprite2D
		if sprite.has_meta("complete_painted_crest"): crests += 1
		if sprite.has_meta("resident_act"): residents.append(int(sprite.get_meta("resident_act")))
		if sprite.has_meta("source_role"):
			if str(sprite.get_meta("source_role")) == "native_generated_detail_background": backgrounds += 1
			else: fixtures += 1
			var owner: String = str(sprite.get_meta("source_owner"))
			if owner != "": owners[owner] = true
			var w: int = sprite.texture.get_width()
			var h: int = sprite.texture.get_height()
			all_pot = all_pot and w <= 1024 and h <= 1024 and (w & (w-1)) == 0 and (h & (h-1)) == 0
var amplitudes: Array[float] = []
for card: Node in v.ambience.curtains:
	var panel: Sprite2D = card.left as Sprite2D
	var factor: Vector2 = (panel.material as ShaderMaterial).get_shader_parameter("pixel_to_legacy")
	amplitudes.append(1.25 / factor.x * panel.scale.x)
return {"backgrounds":backgrounds,"fixtures":fixtures,"owners":owners.size(),"crests":crests,"resident_acts":residents,"curtains":v.ambience.curtains.size(),"all_source_card_textures_pot_and_1024_max":all_pot,"curtain_world_amplitudes":amplitudes,"save_hash":v.m.save_data.hash(),"stars":v.m.opera_stars,"pearls":v.m.pearl_count,"snapshot":v.review_snapshot()}
